import os
import csv
from datetime import datetime, timedelta

log_dir = '/app/logs'
ref_date = datetime(2025, 8, 12).date()

counts = {
    'today': {'ERROR': 0, 'WARNING': 0, 'INFO': 0},
    'last_7_days': {'ERROR': 0, 'WARNING': 0, 'INFO': 0},
    'last_30_days': {'ERROR': 0, 'WARNING': 0, 'INFO': 0},
    'month_to_date': {'ERROR': 0, 'WARNING': 0, 'INFO': 0},
    'total': {'ERROR': 0, 'WARNING': 0, 'INFO': 0}
}

severities = ['ERROR', 'WARNING', 'INFO']

if not os.path.exists(log_dir):
    print(f"Error: {log_dir} does not exist")
    exit(1)

for filename in sorted(os.listdir(log_dir)):
    if filename.endswith('.log'):
        try:
            # Extract date from filename: YYYY-MM-DD_<source>.log
            date_part = filename.split('_')[0]
            file_date = datetime.strptime(date_part, '%Y-%m-%d').date()

            # Determine which periods this file belongs to
            periods = []
            if file_date == ref_date:
                periods.append('today')
            if ref_date - timedelta(days=6) <= file_date <= ref_date:
                periods.append('last_7_days')
            if ref_date - timedelta(days=29) <= file_date <= ref_date:
                periods.append('last_30_days')
            if file_date.month == ref_date.month and file_date.year == ref_date.year and file_date <= ref_date:
                periods.append('month_to_date')

            periods.append('total')

            file_path = os.path.join(log_dir, filename)
            with open(file_path, 'r') as f:
                for line in f:
                    for sev in severities:
                        if f'[{sev}]' in line:
                            for p in periods:
                                counts[p][sev] += 1
                            break
        except Exception as e:
            print(f"Error processing {filename}: {e}")

with open('/app/summary.csv', 'w', newline='') as csvfile:
    fieldnames = ['period', 'severity', 'count']
    writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
    writer.writeheader()

    order = [
        ('today', 'ERROR'), ('today', 'WARNING'), ('today', 'INFO'),
        ('last_7_days', 'ERROR'), ('last_7_days', 'WARNING'), ('last_7_days', 'INFO'),
        ('last_30_days', 'ERROR'), ('last_30_days', 'WARNING'), ('last_30_days', 'INFO'),
        ('month_to_date', 'ERROR'), ('month_to_date', 'WARNING'), ('month_to_date', 'INFO'),
        ('total', 'ERROR'), ('total', 'WARNING'), ('total', 'INFO')
    ]

    for period, sev in order:
        writer.writerow({'period': period, 'severity': sev, 'count': counts[period][sev]})

print("Summary CSV created successfully.")
